def export_pdf(html_path: Path) -> Path:
    candidates = [shutil.which("chrome"), Path(r"C:\Program Files\Google\Chrome\Application\chrome.exe"), Path(r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe")]
    chrome = next((str(p) for p in candidates if p and Path(p).exists()), None)
    if chrome is None:
        raise RuntimeError("No se encontró Google Chrome para exportar la presentación")
    pdf_path = html_path.with_suffix(".pdf")
    with tempfile.TemporaryDirectory() as temp:
        command = [chrome, "--headless", "--disable-gpu", "--no-sandbox", "--no-pdf-header-footer", "--print-to-pdf=" + str(pdf_path), html_path.resolve().as_uri()]
        result = subprocess.run(command, capture_output=True, text=True, timeout=180)
        if result.returncode != 0 or not pdf_path.exists():
            raise RuntimeError("No se pudo exportar el PDF: " + result.stderr[-1000:])
    import pymupdf
    with pymupdf.open(pdf_path) as doc:
        if doc.page_count != 8:
            raise RuntimeError(f"La presentación debe tener 8 diapositivas; produjo {doc.page_count}")
    return pdf_path


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    html_path = OUT / "presentacion.html"
    html_path.write_text(build_html(), encoding="utf-8", newline="\n")
    pdf_path = export_pdf(html_path)
    print(f"Presentación V7: {html_path} · {pdf_path}")


if __name__ == "__main__":
    main()
